17	package org.springframework.samples.petclinic.service;
18	
19	import org.springframework.beans.factory.annotation.Autowired;
20	import org.springframework.samples.petclinic.model.Owner;
21	import org.springframework.stereotype.Component;
22	
23	import java.time.Clock;
24	import java.time.LocalDate;
25	
26	/**
27	 * Scores an owner's membership and maps that score to a numeric level. Points start at 0
28	 * and accrue for each qualifying attribute:
29	 * <ul>
30	 *   <li>+{@value #EMAIL_POINTS} when the owner has an email address on file;</li>
31	 *   <li>+{@value #NO_NAMESAKE_POINTS} when the owner has no namesakes ({@code namesakeCount} is 0);</li>
32	 *   <li>+{@value #LARGE_HOUSEHOLD_POINTS} when the owner's household has {@value #LARGE_HOUSEHOLD_SIZE}
33	 *       or more members;</li>
34	 *   <li>+{@value #TENURE_POINTS} when the owner's tenure exceeds {@value #TENURE_THRESHOLD_DAYS} days.</li>
35	 * </ul>
36	 * The point total maps to a level as 1 (0-1 points), 2 (2-3), 3 (4-5) and 4 (6 or more).
37	 */
38	@Component
39	public class MembershipLevelEvaluator {
40	
41	    /** Points gained when an email address is on file. */
42	    static final int EMAIL_POINTS = 2;
43	
44	    /** Points gained when the owner has no namesakes. */
45	    static final int NO_NAMESAKE_POINTS = 1;
46	
47	    /** Points gained when the owner belongs to a large household. */
48	    static final int LARGE_HOUSEHOLD_POINTS = 2;
49	
50	    /** Points gained when tenure exceeds {@value #TENURE_THRESHOLD_DAYS} days. */
51	    static final int TENURE_POINTS = 3;
52	
53	    /** Household size at or above which {@link #LARGE_HOUSEHOLD_POINTS} apply. */
54	    static final int LARGE_HOUSEHOLD_SIZE = 3;
55	
56	    /** Tenure, in days, that must be exceeded for the tenure points to apply. */
57	    static final long TENURE_THRESHOLD_DAYS = 365;
58	
59	    private final ClinicService clinicService;
60	
61	    private final Clock clock;
62	
63	    @Autowired
64	    public MembershipLevelEvaluator(ClinicService clinicService) {
65	        this(clinicService, Clock.systemDefaultZone());
66	    }
67	
68	    MembershipLevelEvaluator(ClinicService clinicService, Clock clock) {
69	        this.clinicService = clinicService;
70	        this.clock = clock;
71	    }
72	
73	    /**
74	     * @param owner the owner whose membership points are evaluated
75	     * @return the owner's membership points, or {@code null} when the owner is not known
76	     */
77	    public Integer pointsFor(Owner owner) {
78	        if (owner == null) {
79	            return null;
80	        }
81	        int points = 0;
82	        if (owner.hasEmail()) {
83	            points += EMAIL_POINTS;
84	        }
85	        if (hasNoNamesakes(owner)) {
86	            points += NO_NAMESAKE_POINTS;
87	        }
88	        if (hasLargeHousehold(owner)) {
89	            points += LARGE_HOUSEHOLD_POINTS;
90	        }
91	        if (hasQualifyingTenure(owner)) {
92	            points += TENURE_POINTS;
93	        }
94	        return points;
95	    }
96	
97	    /**
98	     * @param owner the owner whose level is evaluated
99	     * @return the owner's membership level, or {@code null} when the owner is not known
100	     */
101	    public Integer levelFor(Owner owner) {
102	        Integer points = pointsFor(owner);
103	        return points == null ? null : levelForPoints(points);
104	    }
105	
106	    /**
107	     * Maps a point total to a membership level: 1 (0-1), 2 (2-3), 3 (4-5), 4 (6 or more).
108	     */
109	    private int levelForPoints(int points) {
110	        if (points <= 1) {
111	            return 1;
112	        }
113	        if (points <= 3) {
114	            return 2;
115	        }
116	        if (points <= 5) {
117	            return 3;
118	        }
119	        return 4;
120	    }
121	
122	    private boolean hasNoNamesakes(Owner owner) {
123	        return owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
124	    }
125	
126	    private boolean hasLargeHousehold(Owner owner) {
127	        return owner.getHouseholdId() != null
128	            && clinicService.countOwnersInHousehold(owner.getHouseholdId()) >= LARGE_HOUSEHOLD_SIZE;
129	    }
130	
131	    private boolean hasQualifyingTenure(Owner owner) {
132	        return owner.tenureInDays(LocalDate.now(clock)) > TENURE_THRESHOLD_DAYS;
133	    }
134	}
