16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Email;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.time.temporal.ChronoUnit;
27	import java.util.*;
28	
29	/**
30	 * Simple JavaBean domain object representing an owner.
31	 *
32	 * @author Ken Krebs
33	 * @author Juergen Hoeller
34	 * @author Sam Brannen
35	 * @author Michael Isvy
36	 */
37	@Entity
38	@Table(name = "owners")
39	public class Owner extends Person {
40	    @Column(name = "title")
41	    private String title;
42	
43	    @Column(name = "address")
44	    @NotEmpty
45	    private String address;
46	
47	    @Column(name = "address_line1")
48	    private String addressLine1;
49	
50	    @Column(name = "address_line2")
51	    private String addressLine2;
52	
53	    @Column(name = "city")
54	    @NotEmpty
55	    private String city;
56	
57	    @Column(name = "telephone")
58	    @NotEmpty
59	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: '+' followed by 8 to 15 digits")
60	    private String telephone;
61	
62	    @Column(name = "email")
63	    @Email
64	    private String email;
65	
66	    @Column(name = "postcode")
67	    private String postcode;
68	
69	    @Column(name = "customer_code")
70	    private String customerCode;
71	
72	    @Column(name = "registration_date")
73	    private LocalDate registrationDate;
74	
75	    @Column(name = "birth_date")
76	    private LocalDate birthDate;
77	
78	    @Column(name = "household_id")
79	    private String householdId;
80	
81	    @Column(name = "namesake_count")
82	    private Integer namesakeCount;
83	
84	    @Column(name = "possible_duplicate")
85	    private Boolean possibleDuplicate;
86	
87	    @Column(name = "possible_duplicate_of")
88	    private Integer possibleDuplicateOf;
89	
90	    @Column(name = "deleted", nullable = false)
91	    private boolean deleted;
92	
93	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
94	    private Set<Pet> pets;
95	
96	    public String getTitle() {
97	        return this.title;
98	    }
99	
100	    public void setTitle(String title) {
101	        this.title = title;
102	    }
103	
104	    public String getAddress() {
105	        return this.address;
106	    }
107	
108	    public void setAddress(String address) {
109	        this.address = address;
110	    }
111	
112	    public String getAddressLine1() {
113	        return this.addressLine1;
114	    }
115	
116	    public void setAddressLine1(String addressLine1) {
117	        this.addressLine1 = addressLine1;
118	    }
119	
120	    public String getAddressLine2() {
121	        return this.addressLine2;
122	    }
123	
124	    public void setAddressLine2(String addressLine2) {
125	        this.addressLine2 = addressLine2;
126	    }
127	
128	    public String getCity() {
129	        return this.city;
130	    }
131	
132	    public void setCity(String city) {
133	        this.city = city;
134	    }
135	
136	    public String getTelephone() {
137	        return this.telephone;
138	    }
139	
140	    public void setTelephone(String telephone) {
141	        this.telephone = telephone;
142	    }
143	
144	    public String getEmail() {
145	        return this.email;
146	    }
147	
148	    public void setEmail(String email) {
149	        this.email = email;
150	    }
151	
152	    /**
153	     * Whether this owner has a non-blank email address on file.
154	     */
155	    public boolean hasEmail() {
156	        return this.email != null && !this.email.isBlank();
157	    }
158	
159	    public String getPostcode() {
160	        return this.postcode;
161	    }
162	
163	    public void setPostcode(String postcode) {
164	        this.postcode = postcode;
165	    }
166	
167	    public String getCustomerCode() {
168	        return this.customerCode;
169	    }
170	
171	    public void setCustomerCode(String customerCode) {
172	        this.customerCode = customerCode;
173	    }
174	
175	    public LocalDate getRegistrationDate() {
176	        return this.registrationDate;
177	    }
178	
179	    public void setRegistrationDate(LocalDate registrationDate) {
180	        this.registrationDate = registrationDate;
181	    }
182	
183	    /**
184	     * The owner's tenure, in whole days elapsed from its registration date up to
185	     * {@code asOf}. Returns 0 when the registration date is absent (as for a brand-new
186	     * owner) or has not yet elapsed.
187	     */
188	    public long tenureInDays(LocalDate asOf) {
189	        if (this.registrationDate == null || asOf == null) {
190	            return 0;
191	        }
192	        return Math.max(0, ChronoUnit.DAYS.between(this.registrationDate, asOf));
193	    }
194	
195	    public LocalDate getBirthDate() {
196	        return this.birthDate;
197	    }
198	
199	    public void setBirthDate(LocalDate birthDate) {
200	        this.birthDate = birthDate;
201	    }
202	
203	    public String getHouseholdId() {
204	        return this.householdId;
205	    }
206	
207	    public void setHouseholdId(String householdId) {
208	        this.householdId = householdId;
209	    }
210	
211	    public Integer getNamesakeCount() {
212	        return this.namesakeCount;
213	    }
214	
215	    public void setNamesakeCount(Integer namesakeCount) {
216	        this.namesakeCount = namesakeCount;
217	    }
218	
219	    public Boolean getPossibleDuplicate() {
220	        return this.possibleDuplicate;
221	    }
222	
223	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
224	        this.possibleDuplicate = possibleDuplicate;
225	    }
226	
227	    public Integer getPossibleDuplicateOf() {
228	        return this.possibleDuplicateOf;
229	    }
230	
231	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
232	        this.possibleDuplicateOf = possibleDuplicateOf;
233	    }
234	
235	    /**
236	     * Whether this owner has been soft-deleted. A soft-deleted owner's row is retained and
237	     * still readable, but it is ignored by the duplicate and identity checks that guard owner
238	     * creation. A newly created owner is not deleted.
239	     */
240	    public boolean isDeleted() {
241	        return this.deleted;
242	    }
243	
244	    public void setDeleted(boolean deleted) {
245	        this.deleted = deleted;
246	    }
247	
248	    protected Set<Pet> getPetsInternal() {
249	        if (this.pets == null) {
250	            this.pets = new HashSet<>();
251	        }
252	        return this.pets;
253	    }
254	
255	    protected void setPetsInternal(Set<Pet> pets) {
256	        this.pets = pets;
257	    }
258	
259	    public List<Pet> getPets() {
260	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
261	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
262	        return Collections.unmodifiableList(sortedPets);
263	    }
264	
265	    public void setPets(List<Pet> pets) {
266	        this.pets = new HashSet<>(pets);
267	    }
268	
269	    public void addPet(Pet pet) {
270	        getPetsInternal().add(pet);
271	        pet.setOwner(this);
272	    }
273	
274	    /**
275	     * Return the Pet with the given name, or null if none found for this Owner.
276	     *
277	     * @param name to test
278	     * @return true if pet name is already in use
279	     */
280	    public Pet getPet(String name) {
281	        return getPet(name, false);
282	    }
283	
284	    /**
285	     * Return the Pet with the given name, or null if none found for this Owner.
286	     *
287	     * @param name to test
288	     * @return true if pet name is already in use
289	     */
290	    public Pet getPet(String name, boolean ignoreNew) {
291	        name = name.toLowerCase();
292	        for (Pet pet : getPetsInternal()) {
293	            if (!ignoreNew || !pet.isNew()) {
294	                String compName = pet.getName();
295	                compName = compName.toLowerCase();
296	                if (compName.equals(name)) {
297	                    return pet;
298	                }
299	            }
300	        }
301	        return null;
302	    }
303	
304	    public Pet getPet(Integer petId) {
305	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
306	    }
307	
308	    @Override
309	    public String toString() {
310	        return new ToStringCreator(this)
311	
312	            .append("id", this.getId())
313	            .append("new", this.isNew())
314	            .append("lastName", this.getLastName())
315	            .append("firstName", this.getFirstName())
316	            .append("address", this.address)
317	            .append("city", this.city)
318	            .append("telephone", this.telephone)
319	            .toString();
320	    }
321	}
