     * @return the owner's membership points, or {@code null} when the owner is not known
     */
    public Integer pointsFor(Owner owner) {
        if (owner == null) {
            return null;
        }
        int points = 0;
        if (owner.hasEmail()) {
            points += EMAIL_POINTS;
        }
        if (hasNoNamesakes(owner)) {
            points += NO_NAMESAKE_POINTS;
